class Classroom {
  count = () => this.students.length;

  constructor(room, students) {
    this.room = room;
    this.students = students;
  }

  labels() {
    return this.students.map((name) => `${name} sits in ${this.room}`);
  }

  report() {
    return `Report for room ${this.room}`;
  }
}

const room = new Classroom("B12", ["Ana", "Ben", "Cleo"]);
console.log(room.labels().join("\n"));
const report = room.report.bind(room);
console.log(report());
const count = room.count;
console.log(`Students: ${count()}`);
